// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A refused request; `reason` is the text the server answered with (empty when none). */
export class HttpError extends Error {
  constructor(message: string, readonly reason: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    const reason = await res.text().catch(() => '');
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, reason, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { type Role, ROLES, rolesKey, useRoles } from './roles';

// The roles assigned on the sheet (any other name is a clerk), and the form that assigns one.
function Roles() {
  const [by] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const roles = useRoles(sheet);
  const [user, setUser] = useState('');
  const [role, setRole] = useState('');
  const queryClient = useQueryClient();

  const save = useMutation({
    mutationFn: (r: { user: string; role: string }) =>
      postJson<Role>(`/api/sheets/${encodeURIComponent(sheet)}/roles`, { ...r, by }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: rolesKey(sheet) });
      setUser('');
      setRole('');
    },
  });
  const submit = useSubmitOnce(save);

  return (
    <section data-testid="roles">
      <h2>Roles</h2>
      <table>
        <thead>
          <tr>
            <th>User</th>
            <th>Role</th>
          </tr>
        </thead>
        <tbody>
          {(roles.data ?? []).map((r) => (
            <tr key={r.user} data-testid={`role-row-${r.user}`}>
              <td data-testid="role-user">{r.user}</td>
              <td data-testid="role-value">{r.role}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <form
        data-testid="role-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ user, role });
        }}
      >
        <input
          data-testid="role-form-user"
          placeholder="User name"
          value={user}
          onChange={(e) => {
            setUser(e.target.value);
            save.reset();
          }}
        />
        <input
          data-testid="role-form-role"
          placeholder={ROLES.join(' or ')}
          list="role-form-roles"
          value={role}
          onChange={(e) => {
            setRole(e.target.value);
            save.reset();
          }}
        />
        <datalist id="role-form-roles">
          {ROLES.map((r) => (
            <option key={r} value={r} />
          ))}
        </datalist>
        <button type="submit" data-testid="role-form-submit" disabled={save.isPending}>
          Set role
        </button>
        {save.isError && (
          <span data-testid="role-form-error" role="alert">
            {' '}
            {save.error instanceof HttpError && save.error.reason ? `${save.error.reason}.` : 'The role was refused.'}
          </span>
        )}
      </form>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 50, Component: Roles });
package net.officefloor.hq.app.role;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Records a stored role: ROLE_SET sheet=<id> by=<user> user=<name> role=<role>. */
public class AuditRoleSet {
    public void audit(@PathVariable("sheetId") String sheetId, @Val RoleInput role, Audit audit) {
        audit.record("ROLE_SET sheet=" + sheetId.trim() + " by=" + role.by() + " user=" + role.user() + " role="
                + role.role().shown());
    }
}
package net.officefloor.hq.app.role;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithRole {
    public void respond(@Val RoleInput role, ObjectResponse<RoleResponse> response) {
        response.send(new RoleResponse(role.user(), role.role().shown()));
    }
}
package net.officefloor.hq.app.role;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithRoles {
    public void respond(@PathVariable("sheetId") String sheetId, RoleStore store,
            ObjectResponse<List<RoleResponse>> response) {
        response.send(store.list(sheetId.trim()));
